import type { ActorCharacter, ActorMode, ActorVoice, Script, ScriptSection } from './types.ts';
import { getScriptPurpose } from './script-purpose.ts';
import { generateId } from './utils.ts';
import { normalizePresentation } from './presentation-preferences.ts';

/**
 * Actor metadata is deliberately bounded independently of the dialogue body.
 * These limits keep a malformed export from turning a cast description into a
 * storage or rendering denial of service while leaving useful room for
 * free-form descriptions.
 */
export const MAX_ACTOR_CHARACTERS = 100;
export const MAX_ACTOR_ID_LENGTH = 200;
export const MAX_ACTOR_NAME_LENGTH = 200;
export const MAX_ACTOR_AGE_LENGTH = 200;
export const MAX_ACTOR_GENDER_LENGTH = 200;
export const MAX_ACTOR_STYLE_LENGTH = 500;
export const MAX_ACTOR_VOICE_ID_LENGTH = 200;
export const MAX_ACTOR_ROLES = 100;
export const MAX_SECTION_NOTES_LENGTH = 500_000;
// Browser/macOS system speech exposes the useful, portable 0.5–2 range.
export const MIN_ACTOR_VOICE_RATE = 0.5;
export const MAX_ACTOR_VOICE_RATE = 2;

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null;
}

function cloneVoiceData(voice: ActorVoice): ActorVoice {
  return {
    engine: voice.engine,
    voiceId: voice.voiceId,
    rate: voice.rate,
  };
}

function isBoundedString(value: unknown, maximum: number, nonEmpty = false): value is string {
  return typeof value === 'string' &&
    value.length <= maximum &&
    (!nonEmpty || value.trim().length > 0);
}

function isBoundedId(value: unknown): value is string {
  return isBoundedString(value, MAX_ACTOR_ID_LENGTH, true);
}

export function isValidActorVoice(value: unknown): value is ActorVoice {
  if (!isRecord(value)) return false;
  return (
    (value.engine === 'system' || value.engine === 'turbo') &&
    isBoundedString(value.voiceId, MAX_ACTOR_VOICE_ID_LENGTH) &&
    typeof value.rate === 'number' &&
    Number.isFinite(value.rate) &&
    value.rate >= MIN_ACTOR_VOICE_RATE &&
    value.rate <= MAX_ACTOR_VOICE_RATE
  );
}

export function isValidActorCharacter(value: unknown): value is ActorCharacter {
  if (!isRecord(value)) return false;
  return (
    isBoundedId(value.id) &&
    isBoundedString(value.name, MAX_ACTOR_NAME_LENGTH, true) &&
    isBoundedString(value.age, MAX_ACTOR_AGE_LENGTH) &&
    isBoundedString(value.gender, MAX_ACTOR_GENDER_LENGTH) &&
    isBoundedString(value.style, MAX_ACTOR_STYLE_LENGTH) &&
    isValidActorVoice(value.voice)
  );
}

/**
 * Validates the cast and selected roles. Section assignments are validated
 * separately because an old/native document can contain an assignment to a
 * character that was later removed. Such an assignment is treated as
 * unassigned by the reader rather than guessed into a different role.
 */
export function isValidActor(value: unknown): value is ActorMode {
  if (!isRecord(value) || typeof value.enabled !== 'boolean') return false;
  if (!Array.isArray(value.characters) || value.characters.length > MAX_ACTOR_CHARACTERS) {
    return false;
  }
  if (!Array.isArray(value.myRoleIds) || value.myRoleIds.length > MAX_ACTOR_ROLES) {
    return false;
  }

  const characterIds = new Set<string>();
  for (const character of value.characters) {
    if (!isValidActorCharacter(character) || characterIds.has(character.id)) return false;
    characterIds.add(character.id);
  }

  const roleIds = new Set<string>();
  return value.myRoleIds.every(roleId => (
    isBoundedId(roleId) &&
    !roleIds.has(roleId) &&
    characterIds.has(roleId) &&
    (roleIds.add(roleId), true)
  ));
}

export function cloneActor(actor: ActorMode): ActorMode {
  return {
    enabled: actor.enabled,
    characters: actor.characters.map(character => ({
      id: character.id,
      name: character.name,
      age: character.age,
      gender: character.gender,
      style: character.style,
      voice: cloneVoiceData(character.voice),
    })),
    myRoleIds: [...actor.myRoleIds],
  };
}

function freshCharacterId(
  usedIds: Set<string>,
  idFactory: () => string,
): string | null {
  for (let attempt = 0; attempt < 100; attempt += 1) {
    const id = idFactory();
    if (isBoundedId(id) && !usedIds.has(id)) {
      usedIds.add(id);
      return id;
    }
  }
  return null;
}

/**
 * Deep-clones an actor configuration while assigning every character a new
 * script-scoped identity. Section assignments are remapped through the
 * returned map by cloneScriptWithRemappedActor.
 */
export function cloneActorWithFreshCharacterIds(
  actor: ActorMode,
  idFactory: () => string = generateId,
  reservedIds: ReadonlySet<string> = new Set<string>(),
): { actor: ActorMode; characterIdMap: Map<string, string> } | null {
  if (!isValidActor(actor)) return null;
  const usedIds = new Set<string>(reservedIds);
  const characterIdMap = new Map<string, string>();
  const characters: ActorCharacter[] = [];
  for (const character of actor.characters) {
    const id = freshCharacterId(usedIds, idFactory);
    if (!id) return null;
    characterIdMap.set(character.id, id);
    characters.push({
      id,
      name: character.name,
      age: character.age,
      gender: character.gender,
      style: character.style,
      voice: cloneVoiceData(character.voice),
    });
  }
  return {
    actor: {
      enabled: actor.enabled,
      characters,
      myRoleIds: actor.myRoleIds
        .map(roleId => characterIdMap.get(roleId))
        .filter((roleId): roleId is string => Boolean(roleId)),
    },
    characterIdMap,
  };
}

/**
 * Remove a cast member without silently assigning their turns to somebody
 * else. The caller should apply unassignment to sections as well.
 */
export function deleteActorCharacter(
  actor: ActorMode,
  characterId: string,
): ActorMode {
  return {
    enabled: actor.enabled,
    characters: actor.characters
      .filter(character => character.id !== characterId)
      .map(character => ({
        id: character.id,
        name: character.name,
        age: character.age,
        gender: character.gender,
        style: character.style,
        voice: cloneVoiceData(character.voice),
      })),
    myRoleIds: actor.myRoleIds.filter(roleId => roleId !== characterId),
  };
}

function cloneSectionData(section: ScriptSection): ScriptSection {
  const cloned: ScriptSection = {
    id: section.id,
    title: section.title,
    content: section.content,
  };
  if (section.notes !== undefined) cloned.notes = section.notes;
  if (section.characterId !== undefined) cloned.characterId = section.characterId;
  return cloned;
}

export function unassignDeletedCharacter(
  sections: ScriptSection[],
  characterId: string,
): ScriptSection[] {
  return sections.map(section => (
    section.characterId === characterId
      ? { ...cloneSectionData(section), characterId: null }
      : cloneSectionData(section)
  ));
}

/**
 * Clone only the persisted script schema. Imported JSON is structurally
 * validated before this helper runs, but explicit fields are still used here
 * so future audio/model blobs cannot hitch a ride through object spreads.
 */
export function cloneScriptData(script: Script): Script {
  const cloned: Script = {
    purpose: getScriptPurpose(script),
    id: script.id,
    title: script.title,
    createdAt: script.createdAt,
    updatedAt: script.updatedAt,
    sections: script.sections.map(cloneSectionData),
  };
  if (script.presentation) {
    cloned.presentation = normalizePresentation(script.presentation);
  }
  if (script.actor) {
    cloned.actor = isValidActor(script.actor)
      ? cloneActor(script.actor)
      : script.actor;
  }
  return cloned;
}

/**
 * Invalid/dangling assignments are retained as an explicit unassigned turn
 * rather than pointed at a different character. This is used when reading
 * older files and before writing new files.
 */
export function normalizeActorSectionReferences(
  actor: ActorMode | undefined,
  sections: ScriptSection[],
): ScriptSection[] {
  if (!actor || !Array.isArray(actor.characters)) {
    return sections.map(cloneSectionData);
  }
  const characterIds = new Set(actor.characters.map(character => character.id));
  return sections.map(section => {
    if (
      section.characterId === undefined ||
      section.characterId === null ||
      characterIds.has(section.characterId)
    ) {
      return cloneSectionData(section);
    }
    return { ...cloneSectionData(section), characterId: null };
  });
}

/**
 * Resolves a section assignment defensively. A dangling characterId is never
 * considered a speaking role, which keeps old/malformed documents visibly
 * unassigned until the user repairs them.
 */
export function getAssignedCharacter(
  script: Pick<Script, 'actor'>,
  section: Pick<ScriptSection, 'characterId'>,
): ActorCharacter | null {
  if (!script.actor || !isValidActor(script.actor)) return null;
  if (typeof section.characterId !== 'string') return null;
  return script.actor.characters.find(character => character.id === section.characterId) ?? null;
}

export function isAssignedToActor(
  script: Pick<Script, 'actor'>,
  section: Pick<ScriptSection, 'characterId'>,
  characterId: string,
): boolean {
  return getAssignedCharacter(script, section)?.id === characterId;
}
import React, { useState, useEffect, useRef } from 'react';
import { Plus, Trash, Users, User, Mic, Volume2, AlertCircle, Square, RefreshCw } from 'lucide-react';
import { listLocalVoices, createSceneSpeech, type LocalVoice } from '@/lib/scene-speech';
import type { ActorCharacter, ActorMode, ScriptSection } from '@/lib/types';
import { toast } from '@/hooks/use-toast';
import { generateId } from '@/lib/utils';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
  DialogDescription,
} from '@/components/ui/dialog';

export type ScriptActor = ActorMode;

export function ActorAuthoringPanel({
  actor,
  onChange,
  onClose,
  sections,
  onDeleteCharacter,
}: {
  actor?: ScriptActor;
  onChange: (actor: ScriptActor) => void;
  onClose: () => void;
  sections: ScriptSection[];
  onDeleteCharacter: (oldId: string, newId: string | null) => void;
}) {
  const currentActor = actor || { enabled: false, characters: [], myRoleIds: [] };
  const [voices, setVoices] = useState<LocalVoice[]>([]);
  const [voiceLoadError, setVoiceLoadError] = useState(false);
  const [loadingVoices, setLoadingVoices] = useState(true);
  const [editingCharId, setEditingCharId] = useState<string | null>(null);

  // Deletion state
  const [deletingCharId, setDeletingCharId] = useState<string | null>(null);
  const [reassignToId, setReassignToId] = useState<string | 'unassign'>('unassign');

  const loadVoices = async () => {
    setLoadingVoices(true);
    setVoiceLoadError(false);
    try {
      const localVoices = await listLocalVoices();
      setVoices(localVoices);
    } catch {
      setVoiceLoadError(true);
    } finally {
      setLoadingVoices(false);
    }
  };

  useEffect(() => {
    loadVoices();
  }, []);

  const speechRef = useRef(createSceneSpeech());
  const [isPreviewing, setIsPreviewing] = useState<string | null>(null);
  const [previewError, setPreviewError] = useState<string | null>(null);
  const abortControllerRef = useRef<AbortController | null>(null);
  const reportStopFailure = () => {
    const message = 'Could not confirm speech stopped. Restart Quickque before using microphone following.';
    setPreviewError(message);
    // The app-level toast survives closure/navigation of the cast panel.
    toast({ title: 'Speech stop failed', description: message, variant: 'destructive' });
  };

  const stopPreview = () => {
    abortControllerRef.current?.abort();
    abortControllerRef.current = null;
    void speechRef.current.stop().catch(reportStopFailure);
    setIsPreviewing(null);
  };

  const handleClose = async () => {
    abortControllerRef.current?.abort();
    abortControllerRef.current = null;
    setIsPreviewing(null);
    try {
      await speechRef.current.stop();
      onClose();
    } catch {
      reportStopFailure();
    }
  };

  const handleSetEditingCharId = (id: string | null) => {
    stopPreview();
    setEditingCharId(id);
  };

  const handleToggle = () => {
    stopPreview();
    onChange({ ...currentActor, enabled: !currentActor.enabled });
  };

  const handleAddChar = () => {
    if (currentActor.characters.length >= 100) return;
    const newChar: ActorCharacter = {
      id: generateId(),
      name: 'New Character',
      age: '',
      gender: '',
      style: '',
      voice: { engine: 'system', voiceId: '', rate: 1.0 },
    };
    onChange({ ...currentActor, characters: [...currentActor.characters, newChar] });
    setEditingCharId(newChar.id);
  };

  const handleUpdateChar = (id: string, updates: Partial<ActorCharacter>) => {
    if (isPreviewing === id) {
      stopPreview();
    }
    onChange({
      ...currentActor,
      characters: currentActor.characters.map((c) => (c.id === id ? { ...c, ...updates } : c)),
    });
  };

  const confirmDeleteChar = () => {
    if (!deletingCharId) return;
    stopPreview();
    // Cast, selected roles and turn references must commit as one transaction.
    onDeleteCharacter(deletingCharId, reassignToId === 'unassign' ? null : reassignToId);
    setDeletingCharId(null);
    setReassignToId('unassign');
  };

  const toggleMyRole = (id: string) => {
    const isMine = currentActor.myRoleIds.includes(id);
    onChange({
      ...currentActor,
      myRoleIds: isMine
        ? currentActor.myRoleIds.filter((roleId) => roleId !== id)
        : [...currentActor.myRoleIds, id],
    });
  };

  const previewVoice = async (char: ActorCharacter) => {
    const wasSame = isPreviewing === char.id;
    stopPreview();
    if (wasSame) return;
    setPreviewError(null);
    setIsPreviewing(char.id);
    const controller = new AbortController();
    abortControllerRef.current = controller;
    try {
      await speechRef.current.speak(
        'This is a preview of the selected local voice.',
        char.voice,
        controller.signal
      );
    } catch {
      if (!controller.signal.aborted && abortControllerRef.current === controller) {
        setPreviewError('Voice preview failed. Refresh local voices, choose an installed system voice, then retry.');
      }
    } finally {
      if (abortControllerRef.current === controller) {
        abortControllerRef.current = null;
        setIsPreviewing(null);
      }
    }
  };

  useEffect(() => {
    return () => {
      // Cleanup reads refs, not the initial render's isPreviewing state.
      abortControllerRef.current?.abort();
      abortControllerRef.current = null;
      void speechRef.current.stop().catch(() => {
        toast({
          title: 'Speech stop failed',
          description: 'Restart Quickque before using microphone following.',
          variant: 'destructive',
        });
      });
    };
  }, []);

  // Moving to another script or changing its saved voice configuration must
  // also cancel a preview, even if this panel remains mounted.
  useEffect(() => {
    abortControllerRef.current?.abort();
    abortControllerRef.current = null;
    void speechRef.current.stop().catch(reportStopFailure);
    setIsPreviewing(null);
  }, [actor]);

  return (
    <div className="absolute inset-y-0 right-0 w-full md:w-96 bg-background border-l border-border shadow-2xl flex flex-col z-50">
      <div className="flex items-center justify-between p-4 border-b border-border">
        <h2 className="text-lg font-semibold flex items-center gap-2">
          <Users className="w-5 h-5 text-primary" />
          Scene Partner Cast
        </h2>
        <button aria-label="Close scene partner cast" onClick={handleClose} className="p-2 hover:bg-muted rounded-full">
          &times;
        </button>
      </div>

      <div className="p-4 border-b border-border flex items-center justify-between">
        <div className="space-y-0.5">
          <label className="text-sm font-medium">Partner audio</label>
          <p className="text-xs text-muted-foreground">Record on another camera. Quickque never records.</p>
        </div>
        <button
          role="switch"
          aria-label="Partner audio"
          aria-checked={currentActor.enabled}
          onClick={handleToggle}
          className={`relative inline-flex h-6 w-11 items-center rounded-full transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary ${
            currentActor.enabled ? 'bg-primary' : 'bg-muted'
          }`}
        >
          <span
            className={`inline-block h-4 w-4 transform rounded-full bg-white transition-transform ${
              currentActor.enabled ? 'translate-x-6' : 'translate-x-1'
            }`}
          />
        </button>
      </div>

      {(
        <div className="flex-1 overflow-y-auto p-4 space-y-6">
          <p className="text-sm font-medium">1. Add cast · 2. Choose your role · 3. Assign turns in the editor · 4. Preview partner voices · 5. Rehearse</p>
          <p className="text-xs text-muted-foreground">Select one or more “My roles” to perform yourself. No selected roles means a full read-through; selecting all roles gives silent cues. Character descriptions are for you, not voice-generation instructions or guarantees.</p>
          {previewError && <p role="alert" className="text-sm text-destructive">{previewError}</p>}
          <div className="space-y-4">
            {currentActor.characters.map((char) => (
              <div
                key={char.id}
                className="bg-card border border-border rounded-xl overflow-hidden shadow-sm"
              >
                <div 
                  className="p-3 bg-muted/50 flex items-center justify-between cursor-pointer"
                  onClick={() => handleSetEditingCharId(editingCharId === char.id ? null : char.id)}
                    onKeyDown={event => {
                      if (event.target === event.currentTarget && (event.key === 'Enter' || event.key === ' ')) {
                        event.preventDefault();
                        handleSetEditingCharId(editingCharId === char.id ? null : char.id);
                      }
                    }}
                    role="button"
                    tabIndex={0}
                    aria-label={`Edit ${char.name}`}
                    aria-expanded={editingCharId === char.id}
                >
                  <div className="flex items-center gap-3">
                    <button
                      onClick={(e) => {
                        e.stopPropagation();
                        toggleMyRole(char.id);
                      }}
                      className={`p-1.5 rounded-md transition-colors ${
                        currentActor.myRoleIds.includes(char.id)
                          ? 'bg-primary text-primary-foreground'
                          : 'bg-background text-muted-foreground hover:bg-background/80'
                      }`}
                      title={currentActor.myRoleIds.includes(char.id) ? "My Role (Silent)" : "Scene Partner (Spoken)"}
                      aria-label={`My role: ${char.name}`}
                      aria-pressed={currentActor.myRoleIds.includes(char.id)}
                    >
                      {currentActor.myRoleIds.includes(char.id) ? <User className="w-4 h-4" /> : <Mic className="w-4 h-4" />}
                    </button>
                    <div>
                      <h3 className="font-medium text-sm">{char.name}</h3>
                      <p className="text-xs text-muted-foreground">
                        {currentActor.myRoleIds.includes(char.id) ? "My role" : "Scene partner"}
                      </p>
                    </div>
                  </div>
                  <div className="flex items-center gap-2">
                    {(
                      <button
                        aria-label={isPreviewing === char.id ? `Stop preview for ${char.name}` : `Preview voice for ${char.name}`}
                        onClick={(e) => {
                          e.stopPropagation();
                          previewVoice(char);
                        }}
                        className="p-1.5 text-muted-foreground hover:text-foreground hover:bg-background rounded"
                      >
                        {isPreviewing === char.id ? <Square className="w-4 h-4 fill-current" /> : <Volume2 className="w-4 h-4" />}
                      </button>
                    )}
                    <button
                      aria-label={`Delete ${char.name}`}
                      onClick={(e) => {
                        e.stopPropagation();
                        setDeletingCharId(char.id);
                      }}
                      className="p-1.5 text-muted-foreground hover:text-destructive hover:bg-destructive/10 rounded"
                    >
                      <Trash className="w-4 h-4" />
                    </button>
                  </div>
                </div>

                {editingCharId === char.id && (
                  <div className="p-4 space-y-4 border-t border-border bg-background">
                    <div className="space-y-1.5">
                      <label className="text-xs font-medium">Character Name</label>
                      <input
                        type="text"
                        aria-label="Character Name"
                        maxLength={200}
                        value={char.name}
                        onChange={(e) => handleUpdateChar(char.id, { name: e.target.value })}
                        className="w-full bg-transparent border border-border rounded-md px-3 py-1.5 text-sm focus:outline-none focus:border-primary"
                        placeholder="e.g. Juliet"
                      />
                    </div>

                    <details className="space-y-3">
                      <summary className="cursor-pointer text-xs font-medium text-muted-foreground">Optional character descriptions</summary>
                    <div className="grid grid-cols-2 gap-4">
                      <div className="space-y-1.5">
                        <label className="text-xs font-medium">Age Description</label>
                        <input
                          type="text"
                          aria-label="Age Description"
                          maxLength={200}
                          value={char.age}
                          onChange={(e) => handleUpdateChar(char.id, { age: e.target.value })}
                          className="w-full bg-transparent border border-border rounded-md px-3 py-1.5 text-sm focus:outline-none focus:border-primary"
                          placeholder="e.g. 20s"
                        />
                      </div>
                      <div className="space-y-1.5">
                        <label className="text-xs font-medium">Gender</label>
                        <input
                          type="text"
                          aria-label="Gender"
                          maxLength={200}
                          value={char.gender}
                          onChange={(e) => handleUpdateChar(char.id, { gender: e.target.value })}
                          className="w-full bg-transparent border border-border rounded-md px-3 py-1.5 text-sm focus:outline-none focus:border-primary"
                          placeholder="e.g. Female"
                        />
                      </div>
                    </div>

                    <div className="space-y-1.5">
                      <label className="text-xs font-medium">Performance Style / Notes</label>
                      <input
                        type="text"
                        aria-label="Performance Style"
                        maxLength={500}
                        value={char.style}
                        onChange={(e) => handleUpdateChar(char.id, { style: e.target.value })}
                        className="w-full bg-transparent border border-border rounded-md px-3 py-1.5 text-sm focus:outline-none focus:border-primary"
                        placeholder="e.g. Enthusiastic, slight accent"
                      />
                    </div>

                    </details>
                    {(
                      <div className="space-y-3 pt-3 border-t border-border">
                        <div className="space-y-1.5">
                          <label className="text-xs font-medium">Voice (Engine)</label>
                          <select
                            aria-label="Voice Engine"
                            value={char.voice.engine}
                            onChange={(e) => handleUpdateChar(char.id, { voice: { ...char.voice, engine: e.target.value as 'system'|'turbo' } })}
                            className="w-full bg-transparent border border-border rounded-md px-3 py-1.5 text-sm focus:outline-none focus:border-primary"
                          >
                            <option value="system">System (Local)</option>
                            <option value="turbo" disabled>Turbo (Unavailable)</option>
                          </select>
                        </div>

                        {char.voice.engine === 'turbo' && (
                          <div className="p-3 bg-amber-500/10 border border-amber-500/20 text-amber-600 dark:text-amber-400 rounded-md text-xs flex gap-2">
                            <AlertCircle className="w-4 h-4 flex-shrink-0" />
                            <p>Turbo is unavailable: Apple Silicon performance, a rights-cleared voice pack and self-contained packaging are not verified. Choose a system voice explicitly.</p>
                          </div>
                        )}

                        <div className="space-y-1.5">
                          <div className="flex items-center justify-between">
                            <label className="text-xs font-medium">Voice Selection</label>
                            {voiceLoadError && (
                              <button onClick={loadVoices} className="flex items-center gap-1 text-[10px] text-destructive hover:text-destructive/80 transition-colors">
                                <RefreshCw className="w-3 h-3" />
                                Retry
                              </button>
                            )}
                          </div>
                          <select
                            aria-label="Voice Selection"
                            value={char.voice.voiceId}
                            onChange={(e) => handleUpdateChar(char.id, { voice: { ...char.voice, voiceId: e.target.value } })}
                            className="w-full bg-transparent border border-border rounded-md px-3 py-1.5 text-sm focus:outline-none focus:border-primary"
                            disabled={char.voice.engine === 'turbo' || voices.length === 0 || loadingVoices}
                          >
                            {!loadingVoices && voices.length > 0 && !voices.some(voice => voice.id === char.voice.voiceId) &&
                              <option value={char.voice.voiceId}>{char.voice.voiceId ? 'Saved voice unavailable — choose a voice' : 'Choose a local voice'}</option>}
                            {loadingVoices ? (
                              <option value="">Loading voices...</option>
                            ) : voices.length === 0 ? (
                              <option value="">No voices found...</option>
                            ) : (
                              voices.map(v => (
                                <option key={v.id} value={v.id}>{v.name} ({v.language})</option>
                              ))
                            )}
                          </select>
                          {!loadingVoices && (voiceLoadError || voices.length === 0) && (
                            <p role="status" className="text-xs text-muted-foreground">
                              {voiceLoadError ? 'Could not list local voices. Retry or check the Mac speech helper installation.' : 'No confirmed local voices are available. Select every character as My role for silent turn cues, switch Partner audio off to read at your own pace, or choose an installed voice in the Mac app.'}
                            </p>
                          )}
                        </div>

                        <div className="space-y-1.5">
                          <div className="flex justify-between">
                            <label className="text-xs font-medium">Speaking Rate ({char.voice.rate.toFixed(1)}x)</label>
                          </div>
                          <input
                            type="range"
                            aria-label="Speaking Rate"
                            disabled={char.voice.engine !== 'system'}
                            min="0.5"
                            max="2"
                            step="0.1"
                            value={char.voice.rate}
                            onChange={(e) => handleUpdateChar(char.id, { voice: { ...char.voice, rate: parseFloat(e.target.value) } })}
                            className="w-full"
                          />
                        </div>
                      </div>
                    )}
                  </div>
                )}
              </div>
            ))}
          </div>

          <button
            onClick={handleAddChar}
            disabled={currentActor.characters.length >= 100}
            className={`w-full py-3 border-2 border-dashed border-border rounded-xl text-muted-foreground hover:bg-muted/50 hover:text-foreground transition-colors flex items-center justify-center gap-2 text-sm font-medium ${
              currentActor.characters.length >= 100 ? 'opacity-50 cursor-not-allowed' : ''
            }`}
          >
            <Plus className="w-4 h-4" />
            {currentActor.characters.length >= 100 ? 'Maximum 100 Characters Reached' : 'Add Character'}
          </button>
        </div>
      )}

      {/* Delete Confirmation Dialog */}
      <Dialog open={!!deletingCharId} onOpenChange={(o) => !o && setDeletingCharId(null)}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Delete Character</DialogTitle>
            <DialogDescription>
              Are you sure you want to remove this character? You can reassign their lines to another character.
            </DialogDescription>
          </DialogHeader>
          <div className="py-4 space-y-4">
            <div className="space-y-2">
              <label className="text-sm font-medium">Reassign lines to:</label>
              <select
                aria-label="Reassign lines to"
                value={reassignToId}
                onChange={(e) => setReassignToId(e.target.value)}
                className="w-full bg-transparent border border-border rounded-md px-3 py-2 text-sm focus:outline-none focus:border-primary"
              >
                <option value="unassign">Unassign lines</option>
                {currentActor.characters
                  .filter((c) => c.id !== deletingCharId)
                  .map((c) => (
                    <option key={c.id} value={c.id}>
                      {c.name}
                    </option>
                  ))}
              </select>
            </div>
          </div>
          <DialogFooter>
            <button
              onClick={() => setDeletingCharId(null)}
              className="px-4 py-2 text-sm font-medium hover:bg-muted rounded-md"
            >
              Cancel
            </button>
            <button
              onClick={confirmDeleteChar}
              className="px-4 py-2 text-sm font-medium bg-destructive text-destructive-foreground hover:bg-destructive/90 rounded-md"
            >
              Delete
            </button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

